#[tokio::test]
async fn streams_an_authorized_event_and_refuses_the_same_repository_to_another_tenant() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let suffix = unique_suffix();
    let tenant_id = format!("tenant-live-feed-{suffix}");
    let repository_id = format!("repository-live-feed-{suffix}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &suffix).await;

    let mut live_feed = LiveFeedStore::connect(&database_url)
        .await
        .expect("the test database should accept Live Feed connections");
    let published = live_feed
        .publish(live_event(tenant_id.clone(), repository_id.clone()))
        .await
        .expect("the authorized repository should publish its Live Feed event");
    let fleet = Arc::new(
        FleetStore::connect(&database_url)
            .await
            .expect("the test database should accept Fleet connections"),
    );
    let authorized = live_feed_routes(LiveFeedApiState::new(
        Arc::new(live_feed),
        fleet.clone(),
        Arc::from(tenant_id.clone()),
    ));
    let response = authorized
        .oneshot(
            Request::builder()
                .uri(format!("/api/v1/live?repository_id={repository_id}"))
                .body(Body::empty())
                .expect("the authorized request should build"),
        )
        .await
        .expect("the authorized request should receive an SSE response");
    assert_eq!(response.status(), StatusCode::OK);
    let mut body = response.into_body();
    let first_frame = body
        .frame()
        .await
        .expect("the SSE response should produce an operation frame")
        .expect("the operation frame should not fail")
        .into_data()
        .expect("the first SSE frame should contain data");
    let event_text =
        String::from_utf8(first_frame.to_vec()).expect("the SSE operation frame should be UTF-8");
    let event_data = event_text
        .lines()
        .find_map(|line| line.strip_prefix("data: "))
        .expect("the operation frame should have JSON data");
    assert_eq!(
        serde_json::from_str::<serde_json::Value>(event_data)
            .expect("the operation data should be JSON"),
        json!({
            "cursor": published.cursor,
            "event_kind": "evidence_conformance",
            "resource_type": "evidence",
            "resource_id": "evidence:integration",
            "change_kind": "attention_required",
            "resource_version": 4,
            "source_ledger_position": 18,
            "projection_position": 17,
            "projection_freshness": "lagging",
            "snapshot_reload": true,
            "emitted_at_seconds": published
                .emitted_at
                .duration_since(UNIX_EPOCH)
                .expect("the persisted event timestamp should be after the Unix epoch")
                .as_secs(),
        })
    );

    let foreign = live_feed_routes(LiveFeedApiState::new(
        Arc::new(
            LiveFeedStore::connect(&database_url)
                .await
                .expect("the test database should accept a second Live Feed connection"),
        ),
        fleet,
        Arc::from(format!("foreign-{tenant_id}")),
    ));
    let foreign_response = foreign
        .oneshot(
            Request::builder()
                .uri(format!("/api/v1/live?repository_id={repository_id}"))
                .body(Body::empty())
                .expect("the foreign request should build"),
        )
        .await
        .expect("the foreign request should receive a refusal response");
    assert_eq!(foreign_response.status(), StatusCode::NOT_FOUND);
}
